from __future__ import annotations

import argparse
from dataclasses import asdict, dataclass
from typing import Any, Callable


@dataclass(frozen=True)
class ToolSpec:
    name: str
    cli_name: str
    category: str
    library_function: str | None
    workflow_function: str | None
    # None = dispatched generically through handlers._generic; a dotted module
    # path = a bespoke handler with its own run(). Internal dispatch detail,
    # not part of the wire-visible MCP contract (dropped in to_dict()).
    handler_module: str | None
    tests_module: str
    annotations: dict[str, Any]
    description: dict[str, str]
    input_schema: dict[str, Any]
    cli_signature: str
    transaction_required: bool = False
    cost_bearing: bool = False
    # Names of input_schema properties that map to positional CLI arguments,
    # in argv order. Structural replacement for regex-parsing positional vs
    # flag layout back out of `cli_signature`. Empty tuple = all flags.
    positional_args: tuple[str, ...] = ()

    @property
    def tool_id(self) -> str:
        return self.name

    @property
    def subcommand(self) -> str:
        return self.cli_name

    @property
    def summary(self) -> str:
        return self.description.get("when") or self.name

    def to_dict(self) -> dict[str, Any]:
        # `positional_args` is an internal CLI-generation hint derived from
        # the canonical signature, not part of the MCP tool contract. Exclude
        # it so the golden MCP snapshot (docs/tool-signatures-snapshot.json)
        # stays the single source of truth for the wire-visible shape.
        data = asdict(self)
        data.pop("positional_args", None)
        # `handler_module` is an internal dispatch hint (None routes through
        # the generic handler), not part of the MCP tool contract. Exclude it
        # so the golden snapshot stays the wire-visible source of truth.
        data.pop("handler_module", None)
        return data

    def requires_transaction(self, _kwargs: dict[str, Any]) -> bool:
        return self.transaction_required

    def is_cost_bearing(self, _kwargs: dict[str, Any]) -> bool:
        return self.cost_bearing


