assert len(TOOLS_BY_ID) == 32

TOOLS: tuple[ToolSpec, ...] = tuple(TOOLS_BY_ID.values())
TRANSACTION_REQUIRED_TOOLS = frozenset(tool.name for tool in TOOLS if tool.transaction_required)
COST_AWARE_TOOLS = frozenset(tool.name for tool in TOOLS if tool.cost_bearing)
BY_SUBCOMMAND: dict[str, ToolSpec] = {tool.cli_name: tool for tool in TOOLS}


def get_tool(name: str) -> ToolSpec | None:
    return TOOLS_BY_ID.get(name) or BY_SUBCOMMAND.get(name)


def from_catalog(name: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    spec = TOOLS_BY_ID[name]

    def decorate(func: Callable[..., Any]) -> Callable[..., Any]:
        setattr(func, "catalog_tool", spec)
        return func

    return decorate


def add_schema_args(parser: argparse.ArgumentParser, spec: ToolSpec) -> None:
    required = set(spec.input_schema.get("required") or [])
    properties = spec.input_schema.get("properties") or {}
    for key, schema in properties.items():
        option = f"--{key.replace('_', '-')}"
        kwargs: dict[str, Any] = {"help": spec.description.get("input", "")}
        if schema.get("type") == "boolean":
            kwargs["action"] = "store_true"
        elif schema.get("type") == "integer":
            kwargs["type"] = int
        elif schema.get("type") == "number":
            kwargs["type"] = float
        elif schema.get("type") == "array":
            kwargs["action"] = "append"
        if "enum" in schema:
            kwargs["choices"] = schema["enum"]
        if key in required:
            kwargs["required"] = True
        parser.add_argument(option, dest=key, **kwargs)
